function isLapsed(handover: OwnershipHandover): boolean {
  return Date.now() >= Date.parse(handover.expiresAt);
}

async function findOpenHandover(orgId: OrgId): Promise<OwnershipHandover | null> {
  const pending = await orgRepo.findLatestPendingHandover(orgId);
  return pending && !isLapsed(pending) ? pending : null;
}

async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:update", {
      allowed: false,
      action: "org:update",
      resourceKind: "organization",
      reason: "denied_by_role",
    });
  }
  return org;
}

/** The offered member's view of the offer: it must exist, be theirs, and not have lapsed. */
async function requireOfferedTo(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  const pending = await orgRepo.findLatestPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending)) throw new OwnershipHandoverError("expired");
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);

  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  if (await findOpenHandover(orgId)) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await orgRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    new Date(),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership handover offered",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const handover = await requireOfferedTo(actor, orgId);

  const newOwner = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  const previous = await memberRepo.findMember(orgId, handover.fromUserId);

  // Promote first so the workspace never has zero owners.
  let promotedFrom: Role | null = null;
  if (newOwner.role !== "owner") {
    promotedFrom = newOwner.role;
    await memberRepo.updateMemberRole(orgId, newOwner.id, "owner");
  }
  const org = await orgRepo.setOrgOwner(orgId, actor.userId);

  let demoted = false;
  if (previous && previous.role === "owner") {
    await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    demoted = true;
  }

  await orgRepo.resolveHandover(handover.id, "accepted", new Date());

  if (promotedFrom !== null) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: newOwner.id,
      from: promotedFrom,
      to: "owner",
    });
  }
  if (demoted && previous) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: previous.id,
      from: "owner",
      to: "admin",
    });
  }
  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: actor.userId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const handover = await requireOfferedTo(actor, orgId);
  return orgRepo.resolveHandover(handover.id, "declined", new Date());
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);
  const open = await findOpenHandover(orgId);
  if (!open) throw new OwnershipHandoverError("nothing_pending");
  return orgRepo.resolveHandover(open.id, "canceled", new Date());
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  return findOpenHandover(orgId);
}
